<?php require_once __DIR__.'/_common.php';$years=ns_years($pdo);$year=ns_year($years);$rows=[];if($year){$s=$pdo->prepare('SELECT frc_team_number,rating,auto_rating,teleop_rating,endgame_rating FROM augur_epa_season_ratings WHERE season_year=? ORDER BY rating DESC LIMIT 4000');$s->execute([$year]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);}ns_head('EPA Rankings');?><section class="page-intro"><span class="eyebrow">SEASON RATINGS</span><h1>EPA <em>Rankings.</em></h1><p>Explore public match-derived EPA across every team in the selected season.</p></section><section class="panel"><div class="section-top"><h2>Leaderboard</h2><?php ns_select_year($years,$year,'/epa/rankings.php');?></div><label class="search-label" for="filter">Filter teams</label><input id="filter" class="filter-input" placeholder="Type a team number…" type="search" data-team-filter><div class="table-scroller"><table id="ratings"><thead><tr><th>Rank</th><th>FRC Team</th><th>EPA</th><th>Auto</th><th>Teleop</th><th>Endgame</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr data-team="<?=intval($r['frc_team_number'])?>"><td><?=$i+1?></td><td><a href="/epa/team.php?team=<?=intval($r['frc_team_number'])?>&year=<?=$year?>">#<?=intval($r['frc_team_number'])?></a></td><?php foreach(['rating','auto_rating','teleop_rating','endgame_rating'] as $k):?><td><?=ns_n($r[$k])?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php if(!$rows)ns_blank();?></section><?php ?><section class="panel"><h2>What do these ratings mean?</h2><p>Learn how public EPA differs from SA-EPA and how scouting informs AUGUR.</p><a href="/epa/intelligence.php">How Neptune Works →</a><p><a href="/epa/api.php">Use this EPA data with the public JSON API →</a></p></section><?php ns_foot();?>